d as (
  select distinct ov.county, d.id district_id, d.district_type, d.label, d.state from essentials.districts d join ov on ov.geo_id=d.geo_id and (d.mtfcc=ov.mtfcc or (ov.mtfcc='G5200V26' and d.mtfcc like 'G5200%') or (d.mtfcc is null))
  union
  select case d.state when 'WI' then '55101' when 'UT' then '49049' when '55' then '55101' when '49' then '49049' when 'IN' then '18105' when '18' then '18105' end, d.id, d.district_type, d.label, d.state from essentials.districts d where d.district_type in ('NATIONAL_UPPER') and d.state in ('WI','UT','55','49','IN','18')
),
offs as (select d.*, o.id office_id, o.title from d join essentials.offices o on o.district_id=d.district_id),
holders as (
  select distinct on (h.politician_id, offs.county) offs.county, 'holder' kind, h.politician_id pid, p.full_name, offs.district_type, offs.label, offs.title, offs.office_id, null::text race
  from offs join essentials.office_current_holder h on h.office_id=offs.office_id join essentials.politicians p on p.id=h.politician_id
  where h.politician_id is not null order by h.politician_id, offs.county, offs.district_type),
cands as (
  select distinct offs.county, 'candidate' kind, rc.politician_id pid, rc.full_name, offs.district_type, offs.label, offs.title, offs.office_id, r.position_name race
  from offs join essentials.races r on r.office_id=offs.office_id join essentials.elections e on e.id=r.election_id
  join essentials.race_candidates rc on rc.race_id=r.id
  where e.election_date >= '2026-10-01' and rc.candidate_status <> 'withdrawn' and coalesce(rc.result,'') not in ('lost','withdrew','not_nominated'))
select * from holders union all select * from cands order by 1,5,6,2,4;
